import hashlib
import html
import math
import random

# illustrations generated by code, only for the demo data; they do not represent real photos

WIDTH, HEIGHT = 400, 300


def _hash(text):
    return int(hashlib.md5(text.encode("utf-8")).hexdigest()[:8], 16)


def _hsl(h, s, l):
    return f"hsl({h % 360:.0f} {s:.0f}% {l:.0f}%)"


def _mirror(body):
    return f'<g>{body}</g><g transform="scale(-1 1)">{body}</g>'


# ---------------------------------------------------------------- beetles
def _beetle(rng, family, species, base_h):
    fam = family.lower()
    horned = any(g in species for g in ("Dynastes", "Megasoma", "Strategus"))
    length, ratio = 190, 0.62
    color_h, color_s, color_l = base_h, 55, 32
    spots = 0
    clubbed_antenna = False
    antenna_length = 1.0
    if fam == "coccinellidae":
        length, ratio = 110, 0.86
        color_h, color_s, color_l = rng.choice([4, 12, 28, 48]), 85, 48
        spots = rng.choice([2, 4, 6, 7])
    elif fam == "scarabaeidae":
        length, ratio = 175, 0.7
        color_h, color_s, color_l = rng.choice([18, 24, 30, 160]), 45, 24
        clubbed_antenna = True
    elif fam == "carabidae":
        length, ratio = 175, 0.5
        color_h, color_s, color_l = rng.choice([210, 150, 270]), 55, 22
    elif fam == "chrysomelidae":
        length, ratio = 120, 0.78
        color_h, color_s, color_l = rng.choice([100, 170, 200, 40]), 70, 40
    elif fam == "cerambycidae":
        length, ratio = 195, 0.38
        color_h, color_s, color_l = rng.choice([25, 35, 50]), 45, 34
        antenna_length = 1.9
    elif fam == "curculionidae":
        length, ratio = 120, 0.62
        color_h, color_s, color_l = 30, 30, 28
    L = length * rng.uniform(0.92, 1.06)
    W = L * ratio
    color = _hsl(color_h, color_s, color_l)
    light = _hsl(color_h, color_s, color_l + 14)
    dark = _hsl(color_h, color_s, max(color_l - 18, 8))
    leg = _hsl(color_h, 30, 14)
    pronotum_color = "#1d1b18" if fam == "coccinellidae" else dark

    parts = []
    for i, y in enumerate((-0.17, 0.02, 0.2)):
        yy = y * L
        reach = 0.72 + 0.12 * i
        parts.append(
            f'<path d="M {W*0.3:.1f} {yy:.1f} L {W*reach:.1f} {yy-L*0.05:.1f} L {W*(reach+0.2):.1f} {yy+L*(0.06+0.05*i):.1f}" '
            f'fill="none" stroke="{leg}" stroke-width="{4.2 if i < 2 else 4.8}" stroke-linecap="round" stroke-linejoin="round"/>'
        )
    legs = _mirror("".join(parts))

    ax = W * 0.55 * antenna_length
    antenna = (
        f'<path d="M {W*0.08:.1f} {-L*0.5:.1f} Q {W*0.25:.1f} {-L*0.58:.1f} {ax:.1f} {-L*0.55-W*0.1:.1f}" '
        f'fill="none" stroke="{leg}" stroke-width="2.4" stroke-linecap="round"/>'
    )
    if clubbed_antenna:
        antenna += f'<ellipse cx="{ax:.1f}" cy="{-L*0.55-W*0.1:.1f}" rx="6" ry="9" fill="{leg}" transform="rotate(30 {ax:.1f} {-L*0.55-W*0.1:.1f})"/>'
    antennae = _mirror(antenna)

    head = f'<ellipse cx="0" cy="{-L*0.455:.1f}" rx="{W*0.21:.1f}" ry="{L*0.075:.1f}" fill="{dark}"/>'
    if fam == "curculionidae":
        head += f'<path d="M 0 {-L*0.5:.1f} L 0 {-L*0.64:.1f}" stroke="{leg}" stroke-width="7" stroke-linecap="round"/>'
    pronotum = (
        f'<path d="M {-W*0.26:.1f} {-L*0.4:.1f} Q {-W*0.46:.1f} {-L*0.34:.1f} {-W*0.44:.1f} {-L*0.21:.1f} '
        f'L {W*0.44:.1f} {-L*0.21:.1f} Q {W*0.46:.1f} {-L*0.34:.1f} {W*0.26:.1f} {-L*0.4:.1f} Z" fill="{pronotum_color}"/>'
    )
    if fam == "coccinellidae":
        pronotum += (
            f'<ellipse cx="{-W*0.2:.1f}" cy="{-L*0.32:.1f}" rx="{W*0.07:.1f}" ry="{L*0.045:.1f}" fill="#f4efdf"/>'
            f'<ellipse cx="{W*0.2:.1f}" cy="{-L*0.32:.1f}" rx="{W*0.07:.1f}" ry="{L*0.045:.1f}" fill="#f4efdf"/>'
        )
    horn = ""
    if horned:
        horn = (
            f'<path d="M {-W*0.07:.1f} {-L*0.36:.1f} Q {-W*0.05:.1f} {-L*0.7:.1f} {W*0.12:.1f} {-L*0.8:.1f} '
            f'Q {W*0.02:.1f} {-L*0.66:.1f} {W*0.07:.1f} {-L*0.36:.1f} Z" fill="{dark}"/>'
            f'<path d="M {-W*0.05:.1f} {-L*0.47:.1f} Q {-W*0.12:.1f} {-L*0.58:.1f} {-W*0.02:.1f} {-L*0.62:.1f}" '
            f'fill="none" stroke="{dark}" stroke-width="5" stroke-linecap="round"/>'
        )
    elytra = (
        f'<path d="M {-W*0.47:.1f} {-L*0.22:.1f} C {-W*0.62:.1f} {L*0.08:.1f} {-W*0.42:.1f} {L*0.46:.1f} 0 {L*0.5:.1f} '
        f'C {W*0.42:.1f} {L*0.46:.1f} {W*0.62:.1f} {L*0.08:.1f} {W*0.47:.1f} {-L*0.22:.1f} Z" fill="{color}"/>'
        f'<path d="M 0 {-L*0.215:.1f} L 0 {L*0.5:.1f}" stroke="{dark}" stroke-width="2.2"/>'
        f'<ellipse cx="{-W*0.2:.1f}" cy="{-L*0.02:.1f}" rx="{W*0.1:.1f}" ry="{L*0.2:.1f}" fill="{light}" opacity="0.5"/>'
    )
    if fam == "coccinellidae":
        points = []
        for _ in range(spots // 2):
            points.append((rng.uniform(0.1, 0.36), rng.uniform(-0.12, 0.38)))
        if spots % 2 == 1:
            elytra += f'<circle cx="0" cy="{-L*0.08:.1f}" r="{W*0.06:.1f}" fill="#1d1b18"/>'
        for x, y in points:
            r = W * rng.uniform(0.055, 0.085)
            elytra += f'<circle cx="{-W*x:.1f}" cy="{L*y:.1f}" r="{r:.1f}" fill="#1d1b18"/><circle cx="{W*x:.1f}" cy="{L*y:.1f}" r="{r:.1f}" fill="#1d1b18"/>'
    if fam == "cerambycidae":
        for k in range(5):
            y = -0.1 + k * 0.12
            elytra += f'<path d="M {-W*0.4:.1f} {L*y:.1f} Q 0 {L*(y+0.03):.1f} {W*0.4:.1f} {L*y:.1f}" stroke="{light}" stroke-width="3" fill="none" opacity="0.6"/>'
    return legs + antennae + horn + head + pronotum + elytra


# ------------------------------------------------------------ butterflies
def _butterfly(rng, family, species, base_h):
    fam = family.lower()
    sp = species.lower()
    tailed = fam == "papilionidae"
    base = _hsl(base_h, 75, 52)
    accent = _hsl(base_h + 40, 80, 60)
    edge = "#231c16"
    pattern = "spots"
    if "danaus" in sp:
        base, accent, pattern = "#d9731f", "#f5e9d2", "spots"
    elif "heliconius" in sp:
        base, accent, pattern = "#1f1b1a", rng.choice(["#d9362b", "#e8c43a"]), "band"
    elif fam == "papilionidae":
        base, accent = rng.choice([("#232220", "#d8c44a"), ("#1c2b3a", "#4fb0d8"), ("#2a2622", "#9fd0a0")])
        pattern = "spots"
    elif fam == "pieridae":
        base, accent, pattern = rng.choice(["#f2efe2", "#f3d84a"]), "#2a2622", "spots"
    elif fam == "lycaenidae" or fam == "riodinidae":
        base, accent, pattern = _hsl(205, 70, 52), "#f4efdf", "spots"
    forewing = "M -5 -10 C -50 -78 -150 -88 -172 -34 C -170 8 -110 24 -5 12 Z"
    hindwing = "M -5 8 C -86 14 -146 48 -122 98 C -92 126 -40 102 -5 44 Z"
    if tailed:
        hindwing = "M -5 8 C -86 14 -146 44 -124 92 L -134 136 C -100 124 -86 112 -64 104 C -30 92 -12 70 -5 44 Z"
    clip = f'<clipPath id="ca"><path d="{forewing}"/></clipPath><clipPath id="cp"><path d="{hindwing}"/></clipPath>'
    wings = (
        f'<path d="{forewing}" fill="{base}" stroke="{edge}" stroke-width="3"/>'
        f'<path d="{hindwing}" fill="{base}" stroke="{edge}" stroke-width="3"/>'
    )
    detail = ""
    if pattern == "band":
        detail += (
            f'<g clip-path="url(#ca)"><path d="M -60 -70 L -100 20" stroke="{accent}" stroke-width="22" opacity="0.95"/>'
            f'<path d="M -128 -64 L -150 -8" stroke="#f4efdf" stroke-width="9"/></g>'
            f'<g clip-path="url(#cp)"><path d="M -40 40 L -100 70" stroke="{accent}" stroke-width="10" opacity="0.9"/></g>'
        )
    else:
        # veins and marginal spots
        for ang in range(-60, 40, 18):
            r = math.radians(ang)
            detail += f'<path d="M -5 0 L {-170*math.cos(r):.1f} {-70*math.sin(r) - 20:.1f}" stroke="{edge}" stroke-width="1.6" opacity="0.5" fill="none"/>'
        for k in range(9):
            t = k / 8
            x = -165 + 110 * t
            y = -26 - 58 * math.sin(t * math.pi) * 0.9
            detail += f'<circle cx="{x:.1f}" cy="{y:.1f}" r="{3 + 2*math.sin(t*math.pi):.1f}" fill="{accent}" opacity="0.95"/>'
        for k in range(6):
            t = k / 5
            detail += f'<circle cx="{-132 + 60*t:.1f}" cy="{86 + 28*math.sin(t*math.pi):.1f}" r="3.4" fill="{accent}" opacity="0.95"/>'
        detail += f'<g clip-path="url(#ca)"><path d="M -5 -10 C -60 -30 -110 -30 -172 -34" stroke="{edge}" stroke-width="12" opacity="0.35" fill="none"/></g>'
    wing = wings + detail
    body = (
        f'<ellipse cx="0" cy="40" rx="5.5" ry="30" fill="#1d1a16"/><ellipse cx="0" cy="-2" rx="7" ry="22" fill="#2a2520"/>'
        f'<circle cx="0" cy="-30" r="7" fill="#1d1a16"/>'
        + _mirror('<path d="M -3 -36 Q -16 -64 -34 -74" stroke="#1d1a16" stroke-width="2.2" fill="none"/><circle cx="-34" cy="-74" r="3.2" fill="#1d1a16"/>')
    )
    return f"<defs>{clip}</defs>" + _mirror(wing) + body


# ----------------------------------------------------------- hymenopterans
def _ant_legs(color):
    out = ""
    for y, dx, dy in ((-40, 52, -22), (-28, 60, 4), (-16, 50, 34)):
        out += (
            f'<path d="M 9 {y} L {dx*0.55:.0f} {y+dy*0.2:.0f} L {dx} {y+dy}" fill="none" stroke="{color}" '
            f'stroke-width="4.4" stroke-linecap="round" stroke-linejoin="round"/>'
        )
    return _mirror(out)


def _ant(rng, family, species, base_h):
    color_h = rng.choice([22, 18, 8, 28, 0])
    dark = "camponotus" in species.lower() or rng.random() < 0.3
    color = _hsl(color_h, 55, 18) if dark else _hsl(color_h, 60, 34)
    light = _hsl(color_h, 55, 44 if not dark else 28)
    leg = _hsl(color_h, 40, 14)
    antenna = _mirror(
        f'<path d="M -7 -86 L -18 -118 L -48 -126" fill="none" stroke="{leg}" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>'
        f'<circle cx="-48" cy="-126" r="3.4" fill="{leg}"/>'
    )
    mandibles = _mirror(f'<path d="M -6 -86 L -14 -96 L -5 -92 Z" fill="{leg}"/>')
    body = (
        _ant_legs(leg)
        + f'<ellipse cx="0" cy="-66" rx="18" ry="21" fill="{color}"/>'
        + _mirror(f'<ellipse cx="-12" cy="-70" rx="4" ry="6" fill="#0d0c0a"/>')
        + f'<path d="M -9 -45 C -16 -38 -14 -20 -8 -10 L 8 -10 C 14 -20 16 -38 9 -45 Z" fill="{light}"/>'
        + f'<ellipse cx="0" cy="-26" rx="10" ry="22" fill="{light}"/>'
        + f'<ellipse cx="0" cy="1" rx="5" ry="7" fill="{color}"/>'
        + f'<ellipse cx="0" cy="40" rx="25" ry="34" fill="{color}"/>'
        + f'<ellipse cx="-8" cy="28" rx="6" ry="14" fill="#ffffff" opacity="0.14"/>'
    )
    return antenna + mandibles + body


def _bee(rng, family, species, base_h):
    wasp = family.lower() == "vespidae"
    yellow = "#e2b32a" if not wasp else "#f0c62e"
    dark = "#2b2218"
    hair = "#8a6a2c" if not wasp else "#2b2218"
    wings = _mirror(
        '<ellipse cx="-44" cy="-52" rx="22" ry="52" transform="rotate(-38 -44 -52)" fill="#cfe4ee" opacity="0.55" stroke="#8fb0c2" stroke-width="1.4"/>'
        '<ellipse cx="-30" cy="-26" rx="14" ry="36" transform="rotate(-62 -30 -26)" fill="#cfe4ee" opacity="0.5" stroke="#8fb0c2" stroke-width="1.2"/>'
    )
    legs = _mirror(
        f'<path d="M -10 -34 L -38 -22 L -48 0" stroke="{dark}" stroke-width="4.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'
        f'<path d="M -10 -28 L -42 -6 L -44 26" stroke="{dark}" stroke-width="4.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'
        f'<path d="M -10 -22 L -34 10 L -32 46" stroke="{dark}" stroke-width="4.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'
    )
    width = 22 if not wasp else 17
    length = 42 if not wasp else 50
    cy = 28 if not wasp else 40
    stripes = ""
    for k in range(4):
        y = cy - length * 0.65 + k * length * 0.42
        stripes += f'<rect x="-40" y="{y:.1f}" width="80" height="{length*0.2:.1f}" fill="{dark if k % 2 == 0 else yellow}"/>'
    clip = f'<clipPath id="ab"><ellipse cx="0" cy="{cy}" rx="{width}" ry="{length}"/></clipPath>'
    abdomen = f'<defs>{clip}</defs><ellipse cx="0" cy="{cy}" rx="{width}" ry="{length}" fill="{yellow}"/><g clip-path="url(#ab)">{stripes}</g>'
    waist = f'<ellipse cx="0" cy="-6" rx="4" ry="6" fill="{dark}"/>' if wasp else ""
    thorax_r = 21 if not wasp else 15
    thorax = f'<ellipse cx="0" cy="-32" rx="{thorax_r}" ry="{thorax_r}" fill="{hair}"/><ellipse cx="0" cy="-32" rx="{thorax_r-7}" ry="{thorax_r-7}" fill="#ffffff" opacity="0.08"/>'
    head = (
        f'<ellipse cx="0" cy="-66" rx="16" ry="14" fill="{dark}"/>'
        + _mirror('<ellipse cx="-11" cy="-68" rx="5" ry="8" fill="#0d0c0a"/>')
    )
    antennae = _mirror(f'<path d="M -5 -78 L -14 -104 L -34 -112" fill="none" stroke="{dark}" stroke-width="2.8" stroke-linecap="round" stroke-linejoin="round"/>')
    return wings + legs + abdomen + waist + thorax + head + antennae


# ------------------------------------------------------------------ main
def render_svg(order, family, species, specimen_id, catalog_number, sex=""):
    rng = random.Random(_hash(f"{specimen_id}-{catalog_number}"))
    base_h = _hash(species) % 360
    order_l = order.lower()
    if order_l == "lepidoptera":
        body, scale, offset = _butterfly(rng, family, species, base_h), 0.95, (200, 138)
    elif order_l == "hymenoptera":
        if family.lower() in ("apidae", "vespidae"):
            body, scale, offset = _bee(rng, family, species, base_h), 1.08, (200, 168)
        else:
            body, scale, offset = _ant(rng, family, species, base_h), 1.08, (200, 165)
    else:
        body, scale, offset = _beetle(rng, family, species, base_h), 1.2 if family.lower() == "coccinellidae" else 0.95, (200, 150)

    angle = rng.uniform(-14, 14) if order_l != "lepidoptera" else rng.uniform(-6, 6)
    final_scale = scale * rng.uniform(0.94, 1.04)
    background = rng.choice(["#ece6d2", "#e8e4d6", "#efe9d8", "#e4e6dc"])
    safe_number = html.escape(catalog_number)
    return (
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {WIDTH} {HEIGHT}" width="{WIDTH}" height="{HEIGHT}">'
        f'<defs><radialGradient id="g" cx="50%" cy="45%" r="75%"><stop offset="0" stop-color="#fbf9f0"/><stop offset="1" stop-color="{background}"/></radialGradient>'
        f'<filter id="s" x="-20%" y="-20%" width="140%" height="140%"><feDropShadow dx="3" dy="6" stdDeviation="5" flood-color="#3b3320" flood-opacity="0.28"/></filter></defs>'
        f'<rect width="{WIDTH}" height="{HEIGHT}" fill="url(#g)"/>'
        f'<g transform="translate({offset[0]} {offset[1]}) rotate({angle:.1f}) scale({final_scale:.3f})" filter="url(#s)">{body}</g>'
        f'<g font-family="monospace" font-size="12" fill="#5b5640">'
        f'<rect x="14" y="268" width="{12 + 7.4*len(catalog_number):.0f}" height="20" rx="3" fill="#fbf9f0" stroke="#b9b290"/>'
        f'<text x="20" y="282">{safe_number}</text>'
        f'<path d="M 316 276 H 380 M 316 270 V 282 M 380 270 V 282" stroke="#5b5640" stroke-width="2" fill="none"/>'
        f'<text x="332" y="266">5 mm</text></g></svg>'
    )
